import{_ as e,o as r,c as a,a2 as n}from"./chunks/framework.CWWEQfK7.js";const h=JSON.parse('{"title":"Glossary","description":"Distinguish project, run, index, authentication, and configuration concepts that are easy to confuse in Ershu.","frontmatter":{"page_id":"reference-glossary","title":"Glossary","description":"Distinguish project, run, index, authentication, and configuration concepts that are easy to confuse in Ershu."},"headers":[],"relativePath":"en/reference/glossary.md","filePath":"en/reference/glossary.md","lastUpdated":1786627803000}'),o={name:"en/reference/glossary.md"};function d(s,t,i,c,l,u){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Project</td><td>A set of repositories analyzed, authorized, and queried together. It is Ershu&#39;s primary access boundary.</td></tr><tr><td>Repository</td><td>A GitHub, GitLab, or trusted local code source in a project, with a target branch, credential, and update policy.</td></tr><tr><td>Full-project analysis (<code>full_project</code>)</td><td>An analysis covering every active repository. Its first successful result establishes the baseline required by later incremental work.</td></tr><tr><td>Incremental analysis</td><td>Analysis of new revisions against an existing full-project baseline, updating project-level results.</td></tr><tr><td>Run</td><td>One analysis request and its complete state: scope, stages, events, checkpoints, usage, and outcome.</td></tr><tr><td>Queue item</td><td>A durable job record that a Worker can claim and renew. An API-created run has not necessarily been executed.</td></tr><tr><td>Run snapshot</td><td>The current run view stored behind the API. The frontend can reload it after a refresh or live-stream disconnect.</td></tr><tr><td>Repository fact</td><td>Tree, file, language, or structural information extracted deterministically from a target revision, separate from model-generated explanation.</td></tr><tr><td>Code index</td><td>Structured output for listing and locating code entities, symbols, and source positions.</td></tr><tr><td>Knowledge relationship</td><td>A connection between files, symbols, or other code entities, used by the graph and context queries.</td></tr><tr><td>Lexical search</td><td>Name and text matching over a completed index, without vector similarity.</td></tr><tr><td>Semantic search</td><td>Meaning-based retrieval using embeddings; it requires Milvus and embedding configuration.</td></tr><tr><td>Hybrid search</td><td>A combination of lexical and semantic results. Supported semantic failures can be reported as an explicit lexical fallback.</td></tr><tr><td>Model channel</td><td>An administrator-managed, enabled provider, model, and credential configuration used for document generation and chat.</td></tr><tr><td>MCP</td><td>Model Context Protocol. Ershu uses it to provide project-scoped, read-only query tools to development agents.</td></tr><tr><td>MCP key</td><td>A project-scoped Bearer credential. The server stores a versioned HMAC-SHA256 digest, not the plaintext key.</td></tr><tr><td>OPAQUE</td><td>The protocol used for web password registration and login. The server stores an OPAQUE password file rather than a recoverable password.</td></tr><tr><td>Runtime setting</td><td>Administrator-managed configuration stored in the database. Its database value can override the same startup default.</td></tr><tr><td>Startup setting</td><td>Configuration read from the process environment. Some values supply runtime defaults; security and connection settings usually apply only at startup.</td></tr><tr><td>Core</td><td>The shared Python package installed into API, Worker, and MCP. It owns common data and rules and is not a network service.</td></tr><tr><td>Source citation</td><td>Repository, revision, path, and location information attached to documents, search, or chat so a reader can verify against source.</td></tr></tbody></table><p>Terms evolve with data models and public contracts. Use the relevant configuration or development page for exact fields rather than inferring unspecified behavior from this table.</p>',3)])])}const m=e(o,[["render",d]]);export{h as __pageData,m as default};
